<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/public-discovery.php';require_once __DIR__.'/app/annotation-ui.php';$viewer=current_user($pdo);$id=(string)($_GET['id']??'');$q=$pdo->prepare('SELECT c.*,u.username,u.display_name FROM collections c JOIN users u ON u.id=c.owner_user_id WHERE c.public_id=?');$q->execute([$id]);$c=$q->fetch();if(!$c||($c['visibility']!=='public'&&(!$viewer||$viewer['id']!=$c['owner_user_id']))){http_response_code(404);exit('Collection not found.');}$q=$pdo->prepare("SELECT a.public_id FROM collection_items ci JOIN annotations a ON a.id=ci.annotation_id WHERE ci.collection_id=? AND a.status='published' ORDER BY ci.created_at DESC");$q->execute([$c['id']]);$scope=$c['visibility']==='public'?null:$viewer;$items=[];foreach($q->fetchAll(PDO::FETCH_COLUMN) as $aid){$row=public_discovery_annotation($pdo,(string)$aid,$scope);if($row)$items[]=$row;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($c['title'])?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/explore.php">Explore</a><a href="/search.php">Search</a><?php if($viewer):?><a href="/saved.php">Saved</a><?php endif?></nav></header><main class="panel article"><div class="meta">Collection by <a href="/profile.php?u=<?=h($c['username'])?>"><?=h($c['display_name'])?></a> · <?=h($c['visibility'])?></div><h1><?=h($c['title'])?></h1><?php if($c['description']):?><p class="commentary"><?=nl2br(h($c['description']))?></p><?php endif?><?php if(!$items):?><div class="card">No annotations in this collection.</div><?php endif?><?php foreach($items as $a):?><?=annotation_ui_card($a,$viewer)?><?php endforeach?></main><?=annotation_ui_scripts($viewer)?></body></html>
